    "/webhooks/refunds/{channel}": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * 退款渠道异步回调
         * @description 渠道推送退款结果，退款单 `30 退款中 → 40 已退款`，
         *     并在同一事务里回写 `order_items.refunded_qty` / `refunded_cents`、
         *     累加 `orders.refunded_cents`、重算 `orders.refund_status`。
         *
         *     **幂等由 `(channel, channel_refund_id)` 唯一索引兜底** ——
         *     与支付回调的 `(channel, channel_txn_id)` 完全同构：重复推送时
         *     第二次写入撞唯一冲突，直接返回 200。这个接口是
         *     `refunds.channel_refund_id` 的**唯一写入路径**。
         *
         *     退款回调的重复率比支付回调只高不低 —— 退款到账往往延迟数小时，
         *     渠道会反复推，所以这条幂等路径必须一次做对。
         *
         *     注意 `30 退款中` **没有通向失败态的边**：渠道调用失败是重试，不是终态。
         *     因此本接口不接受「退款失败」的终局语义，失败只体现为「还没退到」。
         *
         *     签名验证失败返回 401，且不得泄露任何内部状态。
         *
         *     **报文与验签**与支付回调同构：本期实现的是 Keel 的规范报文
         *     `{refund_no, channel_refund_id, amount_cents, refunded_at?}` 加
         *     `X-Keel-Signature: hex(HMAC-SHA256(该店该渠道的回调密钥, 原始请求体))`，
         *     没配密钥一律拒绝。真实渠道的报文与验签由适配器翻译，业务这一段不变。
         *
         *     入账同一事务里还按规则处理库存与券（数据模型 §11）：**未发货**的退款回补
         *     库存到履约门店；整单的货全部退完才把券退回「未使用」（已过期不退）。
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path: {
                    /** @description 余额退款不产生渠道回调，故此处没有 balance。 */
                    channel: "wechat" | "alipay";
                };
                cookie?: never;
            };
            requestBody: {
                content: {
                    "application/json": {
                        [key: string]: unknown;
                    };
                    "application/xml": string;
                };
            };
            responses: {
                /**
                 * @description 已受理（无论首次还是重复）。
                 *
                 *     **业务性结论也回 200**：订单查不到、金额不符、订单已不在待支付、
                 *     报文解不开——这四种渠道重推也没用，让它继续重推只会放大噪音。
                 *     这类结论在服务端留 Error 日志等人处置。
                 */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content?: never;
                };
                /** @description 签名验证失败 */
                401: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content?: never;
                };
                /**
                 * @description 未能入账，**请渠道重推**。基础设施故障（库不可达之类）走这里。
                 *
                 *     这条不是形式：回 200 会让渠道停止重推，而我们确实没入账，
                 *     一笔真实到账就只在日志里留个影。
                 */
                default: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/problem+json": components["schemas"]["Problem"];
                    };
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
